"""Select a connected narrow two-direction Native route before spawning."""
from math import hypot


def _xy(waypoint):
    p=waypoint.transform.location
    return float(p.x),float(p.y)


def _opposing(waypoint):
    for candidate in (waypoint.get_left_lane(),waypoint.get_right_lane()):
        if (candidate is not None and candidate.road_id==waypoint.road_id
                and candidate.lane_id*waypoint.lane_id<0
                and not candidate.is_junction
                and abs(candidate.lane_width-waypoint.lane_width)<=.75):
            return candidate
    raise ValueError('opposite-direction adjacent lane absent')


def route_from(start,step_m=5.0):
    if step_m<=0:raise ValueError('invalid Native sampling step')
    if start.is_junction or not 2.3<=start.lane_width<=3.5:
        raise ValueError('narrow nonjunction lane required')
    chain=[start]
    for _ in range(32):
        choices=[w for w in chain[-1].next(step_m)
                 if w.road_id==start.road_id and w.lane_id==start.lane_id and not w.is_junction]
        if len(choices)!=1:raise ValueError('narrow route is not uniquely connected')
        nxt=choices[0]
        distance=hypot(nxt.transform.location.x-chain[-1].transform.location.x,
                       nxt.transform.location.y-chain[-1].transform.location.y)
        if not .5*step_m<=distance<=1.6*step_m:
            raise ValueError('narrow route has discontinuous sample')
        chain.append(nxt)
    opposite=_opposing(chain[24])
    if hypot(*[a-b for a,b in zip(_xy(opposite),_xy(chain[24]))])>2*start.lane_width+1:
        raise ValueError('opposing lane is not adjacent')
    return {'ego':chain[8],'follower':chain[4],'opposing':opposite,
            'obstruction_site':chain[12], 'chain':chain,
            'road_id':start.road_id,'ego_lane_id':start.lane_id,
            'opposing_lane_id':opposite.lane_id,
            'lane_width_m':start.lane_width}


def select_route(world_map,step_m=5.0):
    errors=[]
    for spawn in world_map.get_spawn_points():
        start=world_map.get_waypoint(spawn.location)
        if start is None:continue
        try:return route_from(start,step_m)
        except ValueError as error:errors.append(str(error))
    raise ValueError('No connected narrow two-direction Native route: '+'; '.join(sorted(set(errors))))

"""Four original-frame RGB sources for the narrow-road slow-speed delivery attempt.

The caller owns the world and encoder sinks. Each sensor is attached to the
subject; a sink must retain its own unscaled source stream under the given name.
This module does not infer traffic impedance or statutory necessity or physical visibility from pixels.
"""
from __future__ import annotations

from dataclasses import dataclass
import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-12.0, 0.0, 10.0), (-15.0, 0.0, 0.0), (1920, 1080), 95),
    "approach": ((1.2, 0.0, 2.0), (0.0, 0.0, 0.0), (1280, 720), 90),
    "reference_corner": ((-5.0, 2.5, 3.5), (-8.0, 0.0, 0.0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0.0, 0.0, 0.0), (1280, 720), 85),
}


@dataclass(frozen=True)
class CameraPlan:
    name: str
    location: tuple[float, float, float]
    rotation: tuple[float, float, float]
    size: tuple[int, int]
    fov: int


def plans():
    return [CameraPlan(name, *spec) for name, spec in CAMERAS.items()]


class FFmpegSourceSink:
    """Retain one lossless, original-resolution BGRA stream from CARLA images."""

    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior source stream; use a fresh attempt")
        width, height = CAMERAS[name][2]
        self.size = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed:
            raise ValueError("Source stream already closed")
        raw = image.raw_data
        if len(raw) != self.size:
            raise ValueError("Source camera raw byte count changed")
        self.process.stdin.write(raw)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Source camera encoder failed")


class SlowCameraCapture:
    def __init__(self, world, carla_module, subject, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named source-camera sinks are required")
        self.sensors = {}
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.callback_errors = []
        self.closed = False
        library = world.get_blueprint_library()
        try:
            for plan in plans():
                bp = library.find("sensor.camera.rgb")
                for key, value in (("image_size_x", plan.size[0]),
                                   ("image_size_y", plan.size[1]),
                                   ("fov", plan.fov), ("sensor_tick", 0.05)):
                    bp.set_attribute(key, str(value))
                loc = carla_module.Location(*plan.location)
                pitch, yaw, roll = plan.rotation
                transform = carla_module.Transform(loc, carla_module.Rotation(pitch, yaw, roll))
                sensor = world.spawn_actor(bp, transform, attach_to=subject)
                self.sensors[plan.name] = sensor
                sensor.listen(lambda image, name=plan.name: self._on_frame(name, image))
        except BaseException:
            self.close()
            raise

    def _on_frame(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original camera frame: " + name)
                expected = CAMERAS[name][2]
                if (image.width, image.height) != expected:
                    raise ValueError("Source camera dimensions changed: " + name)
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.callback_errors.append(error)
                raise
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, timeout_s=10):
        """Join all original source pixels before writing that Native tick."""
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.callback_errors:
                    raise ValueError("Source camera callback failed") from self.callback_errors[0]
                if all(frame in rows for rows in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    missing = sorted(name for name, rows in self.frames.items() if frame not in rows)
                    raise ValueError("Timed out waiting for source camera frame "
                                     + str(frame) + ": " + ", ".join(missing))
                self.condition.wait(remaining)

    def verify_frames(self, frames):
        if self.callback_errors:
            raise ValueError("Source camera callback failed") from self.callback_errors[0]
        expected = set(frames)
        if not expected:
            raise ValueError("No captured original frames")
        for name, observed in self.frames.items():
            if observed != expected:
                raise ValueError("Missing or extra source-camera frames: " + name)
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in self.sensors.values():
                sensor.stop()
                sensor.destroy()

"""Record original Native participant/prop state alongside PipelineCapture.

World, cameras and actor lifetimes belong to the runner. This class retains
only the case-specific sources and original frame map.
"""
import json
from math import hypot
from pathlib import Path


def _point_xy(value):
    return [float(value.x),float(value.y)]


def _actor_state(actor):
    if actor is None or not actor.is_alive:
        raise ValueError('required participant absent from Native world')
    position=actor.get_transform().location
    velocity=actor.get_velocity()
    return _point_xy(position),hypot(velocity.x,velocity.y)


def _prop_geometry(actor):
    if actor is None: return None
    if not actor.is_alive:
        raise ValueError('required physical prop absent from Native world')
    transform=actor.get_transform()
    box=actor.bounding_box
    vertices=box.get_world_vertices(transform)
    if len(vertices)<4:
        raise ValueError('physical prop has no bounding geometry')
    return {'actor_id':int(actor.id),'blueprint_id':actor.type_id,
            'center_xy':_point_xy(transform.location),
            'vertices_xyz':[[float(v.x),float(v.y),float(v.z)] for v in vertices]}


class SlowCaptureSession:
    def __init__(self, output, pipeline_capture, ego, follower, opposing,
                 obstruction, control, context):
        from worker_exchange.native_output import FrameMap
        root=Path(output)
        if context.get('case_branch') not in ('flowing_reference','slow_with_following_traffic',
                                              'slow_for_obstruction','slow_under_control'):
            raise ValueError('exact slow-speed branch required')
        if context['case_branch']=='slow_for_obstruction' and obstruction is None:
            raise ValueError('obstruction branch requires physical prop')
        if context['case_branch']=='slow_under_control' and (control is None or not context.get('regulatory_source')):
            raise ValueError('control branch requires physical device and regulatory source')
        for filename in ('slow_context.json','participant_state.jsonl','prop_state.jsonl','video_frames.jsonl'):
            if (root/filename).exists():
                raise ValueError('Retain prior source; use fresh attempt: '+filename)
        self.pipeline=pipeline_capture
        self.ego,self.follower,self.opposing=ego,follower,opposing
        self.obstruction,self.control=obstruction,control
        (root/'slow_context.json').write_text(json.dumps(context,indent=2)+'\n')
        self.participants=(root/'participant_state.jsonl').open('x')
        self.props=(root/'prop_state.jsonl').open('x')
        self.frames=FrameMap(root/'video_frames.jsonl')
        self.closed=False

    def capture(self, frame, time_s):
        if self.closed: raise ValueError('capture session closed')
        observed={}
        for name,actor in (('ego',self.ego),('follower',self.follower),('opposing',self.opposing)):
            xy,speed=_actor_state(actor)
            observed[name+'_valid']=True
            observed[name+'_xy']=xy
            observed[name+'_speed_mps']=speed
        obstruction=_prop_geometry(self.obstruction)
        control=_prop_geometry(self.control)
        row=self.pipeline.capture(frame,time_s)
        if (row.get('frame'),row.get('time_s'))!=(frame,time_s):
            raise ValueError('PipelineCapture returned another original tick')
        participant={'frame':frame,'time_s':time_s,**observed}
        prop={'frame':frame,'time_s':time_s,
              'obstruction_present':obstruction is not None,
              'obstruction_geometry':obstruction,
              'control_present':control is not None,
              'control_geometry':control,
              # Actual camera visibility is independently audited from pixels.
              'obstruction_visible':None,'control_visible':None}
        self.participants.write(json.dumps(participant)+'\n');self.participants.flush()
        self.props.write(json.dumps(prop)+'\n');self.props.flush()
        self.frames.append(frame,time_s)
        return row

    def close(self):
        if not self.closed:
            self.closed=True
            self.frames.close();self.participants.close();self.props.close()

    def __enter__(self):return self
    def __exit__(self,*_):self.close()

import sys
from pathlib import Path
from types import SimpleNamespace
import unittest
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import runner
class RunnerTest(unittest.TestCase):
    def config(self):
        return {'selected_case_id':'heldout__C136529__NRS-484B-623-1__motor_vehicle_driver__slow_with_following_traffic',
                'law_id':'NRS-484B-623-1','cell_id':'C136529','actor':'motor_vehicle_driver',
                'case_branch':'slow_with_following_traffic','rate_hz':20,'frames':160,'duration_s':8,'cameras':[{'name':n} for n in runner.CAMERAS],
                'case':{'recording_description':{'channels':[]}}}
    def test_exact_identity_and_camera_contract(self):
        self.assertTrue(runner.check_config(self.config()))
        bad=dict(self.config(),frames=100)
        with self.assertRaisesRegex(ValueError,'160 original'):runner.check_config(bad)
        bad=dict(self.config(),selected_case_id='other')
        with self.assertRaisesRegex(ValueError,'exact supported'):runner.check_config(bad)
    def test_speed_sign_selection_requires_physical_native_actor(self):
        sign=SimpleNamespace(id=5,type_id='traffic.speed_limit.30',is_alive=True,
            get_transform=lambda:SimpleNamespace(location=SimpleNamespace(x=5,y=0)))
        ego=SimpleNamespace(get_transform=lambda:SimpleNamespace(location=SimpleNamespace(x=0,y=0)))
        world=SimpleNamespace(get_actors=lambda:SimpleNamespace(filter=lambda pattern:[sign]))
        self.assertIs(runner._find_speed_sign(world,ego),sign)
        with self.assertRaisesRegex(ValueError,'No physical 30'):
            runner._find_speed_sign(world,ego,max_distance_m=1)
    def test_obstruction_control_slows_near_physical_actor(self):
        def actor(y):return SimpleNamespace(get_transform=lambda:SimpleNamespace(location=SimpleNamespace(x=0,y=y)))
        ego=actor(0)
        self.assertEqual(runner._obstruction_target(ego,actor(40),3),3)
        self.assertLess(runner._obstruction_target(ego,actor(11),3),3)
    def test_follower_control_responds_to_gap(self):
        def actor(y,speed):
            return SimpleNamespace(get_transform=lambda:SimpleNamespace(location=SimpleNamespace(x=0,y=y)),
                get_velocity=lambda:SimpleNamespace(x=0,y=speed))
        ego=actor(20,3)
        self.assertGreater(runner._follower_target(ego,actor(0,8)),
                           runner._follower_target(ego,actor(11,8)))
if __name__=='__main__':unittest.main()

import sys
from pathlib import Path
from types import SimpleNamespace
import unittest
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from slow_route import route_from
class Waypoint:
    def __init__(self,index,lane=1,width=2.75):
        self.index=index;self.lane_id=lane;self.lane_width=width;self.road_id=7;self.is_junction=False
        self.transform=SimpleNamespace(location=SimpleNamespace(x=lane*1.375,y=index*5.0,z=0))
    def next(self,step):return [Waypoint(self.index+1,self.lane_id,self.lane_width)] if self.index<32 else []
    def get_left_lane(self):return Waypoint(self.index,-self.lane_id,self.lane_width)
    def get_right_lane(self):return None
class RouteTest(unittest.TestCase):
    def test_narrow_connected_both_directions(self):
        for lane in (-1,1):
            route=route_from(Waypoint(0,lane))
            self.assertEqual(route['ego'].index,8)
            self.assertEqual(route['follower'].index,4)
            self.assertEqual(route['opposing'].index,24)
            self.assertLess(route['ego_lane_id']*route['opposing_lane_id'],0)
    def test_rejects_wide_and_short_road(self):
        with self.assertRaisesRegex(ValueError,'narrow'):route_from(Waypoint(0,width=5))
        class Short(Waypoint):
            def next(self,step):return []
        with self.assertRaisesRegex(ValueError,'uniquely connected'):route_from(Short(0))
if __name__=='__main__':unittest.main()
